-- ============================================================
-- IMPORT PAGU + ANGKAS dari CSV per 30 Sep 2026 (356 baris)
-- Cara pakai: Supabase > SQL Editor > paste file ini > Run (aman diulang).
-- Realisasi/SISA tidak disimpan di sini, masuk via backfill_realisasi_30sept.sql.
-- ============================================================


-- Verifikasi per bidang:
SELECT b.nama AS bidang, COUNT(*) AS baris, SUM(bl.pagu) AS total_pagu FROM public.budget_lines bl JOIN public.bidang b ON b.id=bl.bidang_id WHERE bl.tahun=2026 GROUP BY b.nama ORDER BY b.nama;